const now = new Date();
const oneWeekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

return [{
  json: {
    github_owner: $env.GITHUB_OWNER || 'owner',
    github_repo: $env.GITHUB_REPO || 'repo',
    since_date: oneWeekAgo.toISOString(),
    language: $env.SUMMARY_LANGUAGE || 'EN',
    delivery_channel: $env.DELIVERY_CHANNEL || 'both',
    discord_webhook_url: $env.DISCORD_WEBHOOK_URL || '',
    slack_webhook_url: $env.SLACK_WEBHOOK_URL || ''
  }
}];

const config = $node['Init Config & Date Range'].json;

// 1. Commits
let rawCommits = [];
try {
  rawCommits = $node['Fetch Weekly Commits'].json || [];
  if (!Array.isArray(rawCommits)) rawCommits = [rawCommits];
} catch (e) { rawCommits = []; }

const commits = rawCommits.map(c => ({
  sha: c.sha ? c.sha.slice(0, 7) : '',
  author: c.commit?.author?.name || c.author?.login || 'Unknown',
  message: (c.commit?.message || '').split('\n')[0]
})).filter(c => c.sha);

// 2. Closed Issues (excluding PRs)
let rawIssues = [];
try {
  rawIssues = $node['Fetch Closed Issues'].json || [];
  if (!Array.isArray(rawIssues)) rawIssues = [rawIssues];
} catch (e) { rawIssues = []; }

const issues = rawIssues
  .filter(i => !i.pull_request)
  .map(i => ({
    number: i.number,
    title: i.title,
    author: i.user?.login || 'Unknown',
    closed_at: i.closed_at
  }));

// 3. Merged PRs
let rawPulls = [];
try {
  rawPulls = $node['Fetch Merged PRs'].json || [];
  if (!Array.isArray(rawPulls)) rawPulls = [rawPulls];
} catch (e) { rawPulls = []; }

const sinceTime = new Date(config.since_date).getTime();
const mergedPRs = rawPulls
  .filter(p => p.merged_at && new Date(p.merged_at).getTime() >= sinceTime)
  .map(p => ({
    number: p.number,
    title: p.title,
    author: p.user?.login || 'Unknown',
    merged_at: p.merged_at
  }));

return [{
  json: {
    ...config,
    stats: {
      total_commits: commits.length,
      closed_issues: issues.length,
      merged_prs: mergedPRs.length
    },
    commits,
    issues,
    merged_prs: mergedPRs
  }
}];

const claudeResponse = $input.first().json;
const config = $node['Aggregate Activity Data'].json;

const contentText = claudeResponse?.content?.[0]?.text || 'No summary generated.';
const title = `📊 Weekly Dev Digest: ${config.github_owner}/${config.github_repo}`;

return [{
  json: {
    ...config,
    summary_markdown: contentText,
    summary_title: title,
    discord_payload: {
      username: 'Claude Dev Digest',
      avatar_url: 'https://anthropic.com/favicon.ico',
      embeds: [{
        title: title,
        description: contentText.slice(0, 4000),
        color: 3447003,
        fields: [
          { name: 'Merged PRs', value: String(config.stats.merged_prs), inline: true },
          { name: 'Closed Issues', value: String(config.stats.closed_issues), inline: true },
          { name: 'Commits', value: String(config.stats.total_commits), inline: true }
        ],
        footer: { text: 'Automated by n8n + Claude Sonnet 4' },
        timestamp: new Date().toISOString()
      }]
    },
    slack_payload: {
      text: `${title}\n\n${contentText}`,
      blocks: [
        {
          type: 'header',
          text: { type: 'plain_text', text: title }
        },
        {
          type: 'section',
          text: { type: 'mrkdwn', text: contentText }
        }
      ]
    }
  }
}];
